CREATE TABLE "CorkBoard" ("id" TEXT NOT NULL,"novelId" TEXT NOT NULL,"title" TEXT NOT NULL DEFAULT 'Main Board',"position" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "CorkBoard_pkey" PRIMARY KEY ("id"));
ALTER TABLE "StickyNote" ADD COLUMN "boardId" TEXT, ADD COLUMN "width" INTEGER NOT NULL DEFAULT 220, ADD COLUMN "height" INTEGER NOT NULL DEFAULT 180;
CREATE INDEX "CorkBoard_novelId_position_idx" ON "CorkBoard"("novelId","position"); CREATE INDEX "StickyNote_boardId_idx" ON "StickyNote"("boardId");
ALTER TABLE "CorkBoard" ADD CONSTRAINT "CorkBoard_novelId_fkey" FOREIGN KEY ("novelId") REFERENCES "Novel"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "StickyNote" ADD CONSTRAINT "StickyNote_boardId_fkey" FOREIGN KEY ("boardId") REFERENCES "CorkBoard"("id") ON DELETE CASCADE ON UPDATE CASCADE;